head.script:
scwin.gridView1_oneditkeyup = function(info) {
    var logStr = "rowIndex=" + info.rowIndex + ", colIndex=" + info.colIndex + ", colID=" + info.colID + ", inputType=" + info.inputType;
    logStr += ", oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode;
    WebSquare.logger.printLog(logStr);
    console.log(logStr);
    log = logStr;
};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.__isCheck = function() {
    return log == "rowIndex=0, colIndex=0, colID=col1, inputType=text, oldValue=t=0, newValue=t=0, keyCode=39" || log == "rowIndex=0, colIndex=4, colID=col5, inputType=textarea, oldValue=t=4, newValue=t=4, keyCode=39" || log == "rowIndex=0, colIndex=7, colID=col8, inputType=calendar, oldValue=t=7, newValue=t=7, keyCode=39" || log == "rowIndex=0, colIndex=8, colID=col9, inputType=secret, oldValue=t=8, newValue=t=8, keyCode=39" || log == "rowIndex=0, colIndex=9, colID=col10, inputType=textImage, oldValue=t=9, newValue=t=9, keyCode=39";
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1__col5', 'key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#G_gridView1__col8_input', 'key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.setSimulate4 = function() {
    scwin.simulateWrapper('#G_gridView1__col9', 'key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.setSimulate5 = function() {
    scwin.simulateWrapper('#G_gridView1__col10', 'key-combo', {
        combo: 'RIGHT_ARROW'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 콘솔(F12)실행하여 그리드 영역의 inputType이 text, textarea, calendar, secret, textImage인 항목에 대해 마우스로 더블클릭하여 입력모드에서 키보드 오른쪽방향키를 입력한다.
    //1. Run the sample file and run the console (F12). Then double-click on the input field of the grid area with text, textarea, calendar, secret and textImage.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_4')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_7')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_8')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_9')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate5()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    //Verify step 1. 5개의 inputType에 대해 콘솔창에 값이 보여진다.예로 첫번째 text타입의 콘솔창의 값은 아래와 같다.rowIndex=0, colIndex=0, colID=col1, inputType=text, oldValue=t=0, newValue=t=0, keyCode=39
    //1. The values ​​are displayed in the console window for the five inputType values, for example the values ​​of the console window of the first text type are as follows: redIndex = 0, colIndex = 0, colID = col1, inputType = text, oldValue = t = 0, newValue = t = 0, keyCode = 39
    //has maked testcase on above
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    window.data = [];
    window.data2 = [];
    for (var i = 0; i < 11 * 10; i++) {
        data.push("t=" + i);
    }
    for (var i = 0; i < 11 * 10; i++) {
        data2.push("t=" + i);
        data2.push("t=" + i);
    }
    dataList2.setData(data2);
    dataList1.setData(data);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
